-- check.sql — self-check for: Exercise 7a — the largest department(s) with TOP 1 WITH TIES
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 3 checks ──────────';

-- CHECK 1: Both departments 1 and 2 (4 employees each)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF((SELECT COUNT(*) FROM dbo.vLargestDepartments) = 2 AND NOT EXISTS (SELECT 1 FROM dbo.vLargestDepartments WHERE depNum NOT IN (1, 2) OR numEmployees <> 4), 1, 0);
SET @info = CONCAT(N''view returned: '', (SELECT STRING_AGG(CONCAT(depNum, N''='', numEmployees), N'', '') FROM dbo.vLargestDepartments));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. Both departments 1 and 2 (4 employees each) | Cả phòng 1 và 2 (mỗi phòng 4 người)'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. Both departments 1 and 2 (4 employees each) | Cả phòng 1 và 2 (mỗi phòng 4 người)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: After a hire in department 2 only department 2 remains
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN;
INSERT INTO dbo.tblEmployee (empSSN, empName, depNum) VALUES (30121050102, N''Mới'', 2);
SET @ok = IIF((SELECT COUNT(*) FROM dbo.vLargestDepartments) = 1 AND (SELECT depNum FROM dbo.vLargestDepartments) = 2 AND (SELECT numEmployees FROM dbo.vLargestDepartments) = 5, 1, 0);
SET @info = CONCAT(N''view returned: '', (SELECT STRING_AGG(CONCAT(depNum, N''='', numEmployees), N'', '') FROM dbo.vLargestDepartments));
ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. After a hire in department 2 only department 2 remains | Sau khi phòng 2 tuyển thêm, chỉ còn phòng 2'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. After a hire in department 2 only department 2 remains | Sau khi phòng 2 tuyển thêm, chỉ còn phòng 2', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: Three-way tie after a hire in department 3
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN;
INSERT INTO dbo.tblEmployee (empSSN, empName, depNum) VALUES (30121050103, N''A'', 3);
SET @ok = IIF((SELECT COUNT(*) FROM dbo.vLargestDepartments) = 3, 1, 0);
SET @info = CONCAT(N''rows: '', (SELECT COUNT(*) FROM dbo.vLargestDepartments), N'' (expected 3: departments 1, 2 and 3 with 4 employees each)'');
ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. Three-way tie after a hire in department 3 | Ba phòng đồng hạng sau khi phòng 3 tuyển thêm'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. Three-way tie after a hire in department 3 | Ba phòng đồng hạng sau khi phòng 3 tuyển thêm', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);

